cd /workspace && cat > /tmp/findsrc.mjs <<'EOF'
const BASE='http://localhost:5173';
let seen=new Set();
async function walk(url, parent){
  if(seen.has(url))return; seen.add(url);
  let text; try{ text=await (await fetch(BASE+url,{signal:AbortSignal.timeout(20000)})).text(); }catch(e){ return; }
  if(text.includes('list.d.ts')||text.includes('.vite/deps/get')){
    console.log(`CONTAINS target string: ${url} (imported by ${parent})`);
    const idx=text.indexOf('list.d.ts');
    if(idx>0) console.log('  context: '+text.slice(Math.max(0,idx-120), idx+60).replace(/\n/g,' '));
    const idx2=text.indexOf('.vite/deps/get');
    if(idx2>0) console.log('  context2: '+text.slice(Math.max(0,idx2-120), idx2+60).replace(/\n/g,' '));
    return; // don't descend
  }
  const specs=new Set();
  for(const m of text.matchAll(/import\s*\(\s*["']([^"']+)["']\s*\)/g)) specs.add(m[1]);
  for(const m of text.matchAll(/from\s+["']([^"']+)["']/g)) specs.add(m[1]);
  for(const m of text.matchAll(/import\s+["']([^"']+)["']/g)) specs.add(m[1]);
  const segs=url.split('/').filter(Boolean); const dir=segs.slice(0,-1);
  for(let s of specs){
    let t=null;
    if(s.startsWith('./')||s.startsWith('../')){ const parts=dir.concat(s.split('/')); const out=[]; for(const p of parts){ if(p==='.')continue; if(p==='..')out.pop(); else out.push(p);} t='/'+out.join('/'); }
    else if(s.startsWith('@/')) t='/resources/js/'+s.slice(2);
    else if(s.startsWith('/')||s.startsWith('@vite')) t=s; else continue;
    await walk(t, url);
  }
}
await walk('/resources/js/app.ts', null);
console.log('visited:', seen.size);
